const TafConfig = require('@taf/taf-config');
const _ = require('lodash');
const mysql = require('mysql2/promise');
const logger = require('./logger');

const getDbInfo = function* (cacheName, configServant) {
  const serverName = `${cacheName}DbAccessServer`;
  const configName = `${cacheName}DbAccessServer.conf`;
  const tafConfig = new TafConfig({
    app: 'DCache',
    server: serverName,
    tafConfigObjProxyName: configServant,
  });
  const configObject = yield tafConfig.loadConfigObject(configName, 'c');
  if (_.isEmpty(configObject)) {
    logger.dcache.info('Taf config is not exist, getKeysFromDb return []', serverName, configName);
    return null;
  }
  const dbPostFixLen = configObject.taf.db_conn.PostfixLen;
  const dbDiv = configObject.taf.db_conn.Div;
  const dbPrefix = configObject.taf.db_conn.DbPrefix;
  const tablePostFixLen = configObject.taf.table.PostfixLen;
  const tableDiv = configObject.taf.table.Div;
  const tablePrefix = configObject.taf.table.TableNamePrefix;
  const tableKey = configObject.taf.sigKey.KeyNameInDB;
  const connection = configObject.taf.Connection[0];

  const dbCount = Number.parseInt(Math.pow(10, dbPostFixLen) / dbDiv);
  const tableCount = Math.min(Math.pow(10, tablePostFixLen), tableDiv);

  const dbNames = [];
  const tableNames = [];
  for (let i = 0; i < dbCount; i++) {
    dbNames.push(`${dbPrefix}${_.padStart(i, dbPostFixLen, '0')}`);
  }
  for (let i = 0; i < tableCount; i++) {
    tableNames.push(`${tablePrefix}${_.padStart(i, tablePostFixLen, '0')}`);
  }
  const connOptions = {};
  [ connOptions.host, connOptions.user, connOptions.password, , connOptions.port ] = connection.split(';').map(v => _.trim(v));
  return {
    dbNames, tableNames, tableKey, connOptions,
  };
};

const getKeysFromDb = function* (cacheName, configServant) {
  const dbInfo = yield getDbInfo(cacheName, configServant);
  if (!dbInfo) {
    return [];
  }
  const { dbNames, tableNames, tableKey, connOptions } = dbInfo;
  logger.dcache.info(`DbInfo dbCount: ${dbNames.length}, tableCount: ${tableNames.length}, key:`, tableKey, connOptions);
  let conn,
    allKeyResult;
  try {
    conn = yield mysql.createConnection(connOptions);
    allKeyResult = yield dbNames.map(dbName => {
      const unionSql = _.join(tableNames.map(tableName => `select \`${tableKey}\` from ${dbName}.${tableName}`), ' union all ');
      return conn.query(unionSql);
    });
  } catch (err) {
    logger.dcache.info('getKeysFromDb error', err);
    return [];
  } finally {
    conn.end();
  }
  allKeyResult = allKeyResult.map(v => v[0]);
  allKeyResult = _.flatten(allKeyResult).map(v => v[tableKey]);
  return allKeyResult;
};

module.exports = { getKeysFromDb };
